} from "@/types/organization";

const HANDOVER_LIFETIME_MS = 7 * 24 * 60 * 60 * 1000;

function denyHandoverPermission(): never {
  throw new PermissionDeniedError("org:handover_ownership", {
    action: "org:handover_ownership",
    resourceKind: "organization",
    allowed: false,
    reason: "denied_by_role",
  });
}

async function requireRecordedOwner(actor: Actor, orgId: OrgId) {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  if (org.ownerId !== actor.userId) denyHandoverPermission();
  return org;
}

function refusal(
  reason: ConstructorParameters<typeof OwnershipHandoverError>[0],
): never {
  throw new OwnershipHandoverError(reason);
}

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await requireRecordedOwner(actor, orgId);
  if (toUserId === actor.userId) refusal("self");

  const recipient = await memberRepo.findMember(orgId, toUserId);
  if (!recipient || recipient.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const createdAt = new Date();
  const createdAtIso = createdAt.toISOString();
  const handover = await handoverRepo.createOwnershipHandover({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    createdAt: createdAtIso,
    expiresAt: new Date(createdAt.getTime() + HANDOVER_LIFETIME_MS).toISOString(),
  });
  if (!handover) refusal("pending_exists");

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Ownership transfer offered",
    body: `${actor.userId} invited you to become the owner of ${org.name}`,
    href: `/${org.slug}/settings/members`,
    actorId: actor.userId,
  });

  return handover;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const now = new Date().toISOString();
  const pending = await handoverRepo.findPendingOwnershipHandover(orgId);
  if (!pending) refusal("nothing_pending");

  if (pending.expiresAt <= now) {
    await handoverRepo.markOwnershipHandoverExpired(orgId, pending.id, now);
    if (pending.toUserId === actor.userId) refusal("expired");
    refusal("nothing_pending");
  }
  if (pending.toUserId !== actor.userId) refusal("nothing_pending");

  const accepted = await handoverRepo.acceptOwnershipHandover(
    orgId,
    pending.id,
    actor.userId,
    now,
  );
  if (accepted === "expired") refusal("expired");
  if (!accepted) refusal("nothing_pending");

  for (const change of accepted.roleChanges) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: change.memberId as MemberId,
      from: change.from,
      to: change.to,
    });
  }
  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: pending.fromUserId,
    toUserId: pending.toUserId,
  });

  return accepted.organization;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const now = new Date().toISOString();
  const pending = await handoverRepo.findPendingOwnershipHandover(orgId);
  if (!pending) refusal("nothing_pending");
  if (pending.expiresAt <= now) {
    await handoverRepo.markOwnershipHandoverExpired(orgId, pending.id, now);
    if (pending.toUserId === actor.userId) refusal("expired");
    refusal("nothing_pending");
  }
  if (pending.toUserId !== actor.userId) refusal("nothing_pending");

  const declined = await handoverRepo.resolveOwnershipHandover(
    orgId,
    pending.id,
    "declined",
    now,
  );
  if (!declined) refusal("nothing_pending");
  return declined;
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await requireRecordedOwner(actor, orgId);
  const now = new Date().toISOString();
  const pending = await handoverRepo.findPendingOwnershipHandover(orgId);
  if (!pending) refusal("nothing_pending");
  if (pending.expiresAt <= now) {
    await handoverRepo.markOwnershipHandoverExpired(orgId, pending.id, now);
    refusal("nothing_pending");
  }
  if (pending.fromUserId !== actor.userId) refusal("nothing_pending");

  const canceled = await handoverRepo.resolveOwnershipHandover(
    orgId,
    pending.id,
    "canceled",
    now,
  );
  if (!canceled) refusal("nothing_pending");
  return canceled;
}

export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  const now = new Date().toISOString();
  await handoverRepo.expireLapsedOwnershipHandovers(orgId, now);
  return handoverRepo.findPendingOwnershipHandover(orgId);
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
