            isActiveSegment(pathname, href)
              ? "bg-neutral-200 font-medium"
              : "hover:bg-neutral-100",
          )}
        >
          {item.label}
        </Link>
        {item.children !== undefined && item.children.length > 0 ? (
          <ul className="ml-3 mt-0.5 space-y-0.5">
            {item.children.map(renderItem)}
          </ul>
        ) : null}
      </li>
    );
  }

  return (
    <nav className="app-sidebar flex w-56 shrink-0 flex-col gap-4 border-r p-3">
      <OrgSwitcher
        organizations={organizations ?? [org]}
        currentSlug={org.slug}
      />

      <ul className="space-y-0.5">{primary.map(renderItem)}</ul>

      {mayReadProjects && projects.length > 0 ? (
        <section>
          <h2 className="px-2 text-xs font-medium uppercase text-neutral-500">
            Projects
          </h2>
          <ul className="mt-1 space-y-0.5">
            {projects.map((project) => {
              const href = projectPath(org.slug, project.slug);
              return (
                <li key={project.id}>
                  <Link
                    href={href}
                    className={cn(
                      "flex items-center justify-between rounded px-2 py-1 text-sm",
                      isActiveSegment(pathname, href)
                        ? "bg-neutral-200 font-medium"
                        : "hover:bg-neutral-100",
                    )}
                  >
                    <span className="truncate">{project.name}</span>
                    {publicProjectsOn && project.visibility === "public" ? (
                      <span className="text-xs text-neutral-500">public</span>
                    ) : null}
                  </Link>
                </li>
              );
            })}
          </ul>
        </section>
      ) : null}

      {settings.length > 0 ? (
        <section className="mt-auto">
          <h2 className="px-2 text-xs font-medium uppercase text-neutral-500">
            Settings
          </h2>
          <ul className="mt-1 space-y-0.5">{settings.map(renderItem)}</ul>
        </section>
      ) : null}
    </nav>
  );
}
  // A membership the caller does not have resolves to null, which is the same
  // 404 as an org that does not exist — see `_lib/tenant-context.ts`.
  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) {
    notFound();
  }
  assertOrgScope(actor, org.id);

  const flags = snapshotFlags(buildFlagContext(actor, org));

  const [projects, notifications, limitChecks] = await Promise.all([
    listProjects(actor, { orgId: org.id, limit: SIDEBAR_PROJECT_LIMIT }),
    listNotifications(actor, {
      orgId: org.id,
      recipientId: actor.userId,
      unreadOnly: true,
      limit: 1,
    }),
    // Evaluated once per navigation so `usePlanLimits()` in the client tree
    // reads a real measurement instead of falling back to "no data".
    Promise.all(
      SHELL_LIMIT_RESOURCES.map((resource) => checkLimit(org.id, resource, 0)),
    ),
  ]);

  return (
    <OrgProvider
      org={org}
      actor={actor}
      flags={flags}
      limitChecks={limitChecks}
    >
      <DashboardShell
        org={org}
        actor={actor}
        flags={flags}
        projects={projects.items.map((row) => row.project)}
        unreadCount={notifications.total}
        pathname={`/${orgSlug}`}
        panel={props.panel}
      >
        {props.children}
      </DashboardShell>
    </OrgProvider>
  );
}

