        org={org}
        actor={actor}
        flags={ALL_FLAGS}
        projects={[]}
        pathname="/acme"
      />,
    );

    const expected = visibleNav(SIDEBAR_NAV, actor, ALL_FLAGS);
    for (const item of expected) {
      expect(screen.getAllByRole("link", { name: item.label }).length).toBeGreaterThan(0);
    }
  });

