    const org = makeOrganization();
    const actor = makeActor({ role: "viewer", orgId: org.id });

    render(
      <AppSidebar
        org={org}
        actor={actor}
        flags={ALL_FLAGS}
        projects={[]}
        pathname="/acme"
      />,
    );

    expect(screen.queryByRole("link", { name: "Activity" })).not.toBeInTheDocument();
  });

