function resourceFor(spec: CommandSpec, actor: Actor): PermissionResource {
  switch (spec.scope) {
    case "billing":
      return billingResource(actor.orgId);
    case "activity":
      return activityResource(actor.orgId);
    default:
      // Creation and navigation are not scoped to an existing row, so the
      // organization is the resource the role matrix is asked about.
      return organizationResource(actor.orgId);
  }
}

export function buildCommandGroups(
  org: Organization,
  actor: Actor,
  flags: FeatureFlagSnapshot,
): readonly CommandGroup[] {
  const context = orgFlagContext(org, actor);
  // The snapshot was evaluated when the layout rendered; a flag flipped since
  // then is still honoured by re-evaluating against the live context.
  const flagOn = (flag: FeatureFlagKey): boolean =>
    flags[flag] === true || isEnabled(flag, context);

  const groups = new Map<string, CommandItemSpec[]>();

  for (const spec of COMMAND_SPECS) {
    if (spec.flag !== undefined && !flagOn(spec.flag)) continue;
    if (spec.scope === "billing" && actor.userId !== org.ownerId) continue;
    if (
      spec.action !== undefined &&
      !can(actor, spec.action, resourceFor(spec, actor))
    ) {
      continue;
    }
    const items = groups.get(spec.heading) ?? [];
    items.push({
      id: spec.id,
      label: spec.label,
      ...(spec.hint !== undefined ? { hint: spec.hint } : {}),
      ...(spec.shortcut !== undefined ? { shortcut: spec.shortcut } : {}),
    });
    groups.set(spec.heading, items);
  }

  return [...groups.entries()].map(([heading, items]) => ({ heading, items }));
}
/**
 * Upgrade prompt shown when seats are exhausted.
 *
 * Upgrade links are shown only to the recorded organization owner.
 */
import Link from "next/link";
import { Alert } from "@/components/ui/alert";
import { formatCount, formatLimit } from "@/lib/format";
import { settingsPath } from "@/lib/url";
import type { LimitCheck } from "@/types/billing";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { ReactElement } from "react";

export type SeatLimitBannerProps = {
  check: LimitCheck;
  orgSlug: string;
  actor: Actor;
  ownerId: UserId;
};

export function SeatLimitBanner(
  props: SeatLimitBannerProps,
): ReactElement | null {
  const { check, orgSlug, actor, ownerId } = props;

  // Nothing to say until the org is actually at the wall.
  if (check.resource !== "seats" || !check.exceeded) return null;

  // Only the actor who could actually pay is offered the upgrade link.
  const mayUpgrade = actor.userId === ownerId;

  return (
    <Alert tone="warning" title="All seats are in use">
      The {check.plan} plan includes {formatLimit(check.limit)} seats and{" "}
      {formatCount(check.used)} are taken, so new invitations will be refused.
      {mayUpgrade ? (
        <>
          {" "}
          <Link
            href={settingsPath(orgSlug, "billing")}
            className="font-medium underline"
          >
            Upgrade the plan
          </Link>{" "}
          to add more.
        </>
      ) : (
        " Ask an owner to upgrade the plan."
      )}
    </Alert>
  );
}
